const app = document.querySelector('#app');
const modalRoot = document.querySelector('#modal-root');
const state = { user:null, categories:[], notifications:[], filters:{q:'',category:'',format:'',city:'',sort:'new',page:1}, requestTab:'all', adminTab:'overview' };
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmtDate = value => value ? new Date(value.includes('T') ? value : value.replace(' ','T')+'Z').toLocaleString('ru-RU',{day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}) : '—';
const initials = name => String(name||'?').split(/\s+/).slice(0,2).map(s=>s[0]).join('').toUpperCase();
const avatar = (name,big=false,image='') => image ? `<span class="avatar ${big?'big':''}"><img src="${esc(image)}" alt="Аватар ${esc(name)}"></span>` : `<span class="avatar ${big?'big ':''}${name?.charCodeAt(0)%3===0?'purple':name?.charCodeAt(0)%3===1?'orange':''}">${esc(initials(name))}</span>`;
const statusName = {PENDING:'Ожидает ответа',ACCEPTED:'Подтверждена',AWAITING_CONFIRMATION:'Ждёт подтверждения',COMPLETED:'Завершена',REJECTED:'Отклонена',CANCELLED:'Отменена',DISPUTED:'Открыт спор',RESOLVED:'Спор решён'};
const status = value => `<span class="status ${esc(value)}">${statusName[value]||esc(value)}</span>`;
const route = () => location.pathname==='/admin' ? 'admin' : (location.hash.slice(2).split('/')[0]||'home');
const routeId = () => Number(location.hash.slice(2).split('/')[1]);
function nav(to){ if(to==='admin'){location.href='/admin';return;} if(location.pathname==='/admin'){location.href='/#/'+to;return;} location.hash='/'+to; window.scrollTo(0,0); }
async function api(url,options={}) { const r=await fetch('/api'+url,{credentials:'same-origin',headers:{'Content-Type':'application/json'},...options}); let data; try{data=await r.json();}catch{throw Error('Ошибка ответа сервера');} if(!r.ok) throw Error(data.error||'Произошла ошибка'); return data; }
const post=(url,body={})=>api(url,{method:'POST',body:JSON.stringify(body)});
const patch=(url,body={})=>api(url,{method:'PATCH',body:JSON.stringify(body)});
function toast(message){const e=document.createElement('div');e.className='toast-item';e.textContent=message;document.querySelector('#toast').append(e);setTimeout(()=>e.remove(),4500);}
function error(e){toast(e.message||'Произошла ошибка');}
function requireLogin(){if(state.user)return true; authModal();return false;}
function header(){ const r=route(),user=state.user; return `<header class="site-header"><div class="container header-inner"><button class="mobile-menu" data-action="menu" aria-label="Открыть меню">☰</button><a class="logo" href="/#/home"><span class="logo-mark" aria-hidden="true"></span><span>skill<span>barter</span></span></a><nav class="nav" id="nav"><a class="${r==='home'?'active':''}" href="/#/home">Главная</a><a class="${r==='catalog'||r==='offer'?'active':''}" href="/#/catalog">Найти помощь</a>${user&&user.role==='user'?`<a class="${r==='requests'||r==='request'?'active':''}" href="/#/requests">Мои заявки</a><a class="${r==='my-offers'?'active':''}" href="/#/my-offers">Мои услуги</a>`:''}${user?.role==='admin'?`<a href="/admin">Админ-панель</a>`:''}</nav><div class="header-actions">${user?`<a class="balance-pill" href="/#/wallet">✳ ${user.available} <small>мин</small></a><button class="profile-chip" data-action="profile-menu" title="Профиль">${avatar(user.name,false,user.avatar_file)} <span>${esc(user.name.split(' ')[0])}</span></button>`:`<button class="btn secondary small" data-action="login">Войти</button><button class="btn small" data-action="register">Регистрация</button>`}</div></div></header>`; }
function footer(){return `<footer class="footer"><div class="container footer-inner"><a class="logo" href="/#/home"><span class="logo-mark" aria-hidden="true"></span><span>skill<span>barter</span></span></a><span>Знания ценнее, когда ими делятся. © ${new Date().getFullYear()} SkillBarter</span><span>Один час помощи = один час возможностей</span></div></footer>`;}
function shell(content){app.innerHTML=header()+content+footer();if(state.user?.role==='user'){const count=state.notifications.filter(n=>!n.read).length;app.querySelector('.header-actions')?.insertAdjacentHTML('afterbegin',`<button class="notification-button" data-action="notifications" aria-label="Уведомления">♧${count?`<span>${count}</span>`:''}</button>`);}}
function loading(){shell('<div class="spinner" aria-label="Загрузка"></div>');}
const categoryImages={1:'development',2:'languages',3:'design',4:'education',5:'career',6:'other'};
const categoryDescriptions={1:'Создавайте и исследуйте',2:'Говорите увереннее',3:'Воплощайте идеи',4:'Узнавайте новое',5:'Развивайте свой путь',6:'Найдите своё вдохновение'};
function categoryCard(c){return `<button class="category" data-action="category" data-id="${c.id}"><span class="category-media"><img src="/images/${categoryImages[c.id]||'other'}.png" alt="" loading="lazy"></span><span class="category-info"><span><strong>${esc(c.name)}</strong><small>${esc(categoryDescriptions[c.id]||'Откройте новые навыки')}</small></span><span class="category-arrow" aria-hidden="true">↗</span></span></button>`;}
function visual(offer,extra=''){const image=categoryImages[offer.category_id]||'other';return `<div class="offer-visual ${extra}"><img src="/images/${image}.png" alt="" loading="lazy"></div>`;}
function offerCard(o,favs=[]){return `<article class="offer-card">${visual(o)}<a class="card-hit" href="/#/offer/${o.id}" aria-label="Открыть услугу: ${esc(o.title)}"></a><button class="fav ${favs.includes(o.id)?'on':''}" data-action="fav" data-id="${o.id}" aria-label="В избранное">${favs.includes(o.id)?'♥':'♡'}</button><div class="offer-content"><div class="card-top"><span>${esc(o.category)}</span><span>◷ ${o.min_minutes}–${o.max_minutes} мин</span></div><h3>${esc(o.title)}</h3><p>${esc(o.description)}</p><div class="tags"><span class="tag">${esc(o.format)}</span><span class="tag">${esc(o.level)}</span>${o.city?`<span class="tag">${esc(o.city)}</span>`:''}</div><div class="card-foot"><a class="provider" href="/#/user/${o.user_id}">${avatar(o.provider,false,o.provider_avatar)} ${esc(o.provider)}</a><span class="rating">★ ${o.rating||'Новый'} <span>${o.review_count?'('+o.review_count+')':''}</span></span></div></div></article>`;}
function empty(title,copy,action=''){return `<div class="empty"><div class="empty-icon">✦</div><h3>${esc(title)}</h3><p>${esc(copy)}</p>${action}</div>`;}
async function home(){loading();const data=await api('/offers');const feature=data.offers.slice(0,3);shell(`<main><section class="hero"><div class="container hero-grid"><div class="hero-copy"><span class="eyebrow">Знания ↔ время</span><h1>Умеешь что-то? <em>Обменяй на новое.</em></h1><p>Делитесь тем, что умеете, и учитесь у других. Здесь за помощь благодарят временем, а не деньгами.</p><div class="hero-actions"><button class="btn" data-action="go-catalog">Найти помощь <span>↗</span></button><button class="btn outline" data-action="new-offer">Предложить навык</button></div><div class="hero-proof"><div class="avatar-stack">${avatar('Айару')}${avatar('Сымбат')}${avatar('Баянсулу')}</div><span>Сообщество, где каждый может быть полезен</span></div></div><div class="hero-art" aria-hidden="true"><div class="art-blob"></div><div class="art-orbit"></div><div class="art-center">✳</div><div class="art-card one"><span class="art-icon">⌘</span><span>Программирование<small>Делимся опытом</small></span></div><div class="art-card two"><span class="art-icon pink">◎</span><span>Английский язык<small>Учимся вместе</small></span></div><div class="art-card three"><span class="art-icon yellow">✦</span><span>+60 минут<small>На вашем балансе</small></span></div><span class="float-dot"></span><span class="float-dot two"></span></div></div></section><section class="section alt"><div class="container"><div class="section-head"><div><span class="eyebrow">Откройте новое</span><h2>Чему хотите научиться?</h2><p>Найдите человека, который поможет вам сделать следующий шаг.</p></div></div><div class="categories">${state.categories.map(categoryCard).join('')}</div></div></section><section class="section"><div class="container"><div class="section-head"><div><span class="eyebrow">Рекомендуем</span><h2>Навыки рядом с вами</h2><p>Знакомьтесь, учитесь и обменивайтесь опытом.</p></div><button class="link" data-action="go-catalog">Все предложения →</button></div><div class="card-grid">${feature.map(o=>offerCard(o,data.favorites)).join('')}</div></div></section><section class="section alt"><div class="container"><div class="section-head"><div><span class="eyebrow">Просто и честно</span><h2>Как работает обмен</h2></div></div><div class="how"><div class="step"><span class="step-num">01</span><h3>Найдите помощь</h3><p>Выберите навык, удобный формат и отправьте заявку исполнителю.</p></div><div class="step"><span class="step-num">02</span><h3>Согласуйте встречу</h3><p>После принятия заявки минуты резервируются. Общайтесь в чате и готовьтесь к встрече.</p></div><div class="step"><span class="step-num">03</span><h3>Обменяйтесь опытом</h3><p>Подтвердите результат — минуты перейдут исполнителю, а вы сможете оставить отзыв.</p></div></div></div></section><section class="section"><div class="container"><div class="cta-band"><div><span class="eyebrow" style="color:#b9e7b4">Начните сегодня</span><h2>У каждого есть чему научить</h2><p>Создайте профиль и получите 120 стартовых минут.</p></div><button class="btn light" data-action="${state.user?'new-offer':'register'}">${state.user?'Предложить навык':'Присоединиться'} ↗</button></div></div></section></main>`);}
async function catalog(){loading();const f=state.filters,q=new URLSearchParams();for(const [k,v] of Object.entries(f))if(v)q.set(k,v);const data=await api('/offers?'+q);shell(`<main class="page"><div class="container"><div class="page-header"><div><span class="eyebrow">Каталог помощи</span><h1>Найдите свой навык</h1><p>Время — общая валюта. Выбирайте то, что вам интересно.</p></div><button class="btn" data-action="new-offer">+ Предложить навык</button></div><form id="filters" class="filters"><input class="input" name="q" placeholder="Поиск по названию или описанию" value="${esc(f.q)}" aria-label="Поиск"><select class="select" name="category" aria-label="Категория"><option value="">Все категории</option>${state.categories.map(c=>`<option value="${c.id}" ${String(f.category)===String(c.id)?'selected':''}>${esc(c.name)}</option>`).join('')}</select><select class="select" name="format" aria-label="Формат"><option value="">Любой формат</option><option ${f.format==='Онлайн'?'selected':''}>Онлайн</option><option ${f.format==='Офлайн'?'selected':''}>Офлайн</option></select><input class="input" name="city" placeholder="Город" value="${esc(f.city)}" aria-label="Город"><select class="select" name="sort" aria-label="Сортировка"><option value="new" ${f.sort==='new'?'selected':''}>Сначала новые</option><option value="rating" ${f.sort==='rating'?'selected':''}>По рейтингу</option></select><button class="btn">Найти</button></form><p class="muted">Найдено предложений: ${data.total}</p>${data.offers.length?`<div class="card-grid">${data.offers.map(o=>offerCard(o,data.favorites)).join('')}</div><div class="pagination"><button class="btn secondary small" data-action="page" data-page="${data.page-1}" ${data.page<=1?'disabled':''}>← Назад</button><span>${data.page} из ${data.pages}</span><button class="btn secondary small" data-action="page" data-page="${data.page+1}" ${data.page>=data.pages?'disabled':''}>Вперёд →</button></div>`:empty('Ничего не найдено','Попробуйте изменить запрос или выбрать другую категорию.')}</div></main>`);}
async function offerPage(){loading();const {offer:o,favorite}=await api('/offers/'+routeId());shell(`<main class="page"><div class="container"><p class="muted"><a href="/#/catalog">Каталог</a> / ${esc(o.category)}</p><div class="detail-grid"><div>${visual(o,'detail-hero')}<span class="eyebrow">${esc(o.category)}</span><h1 class="detail-title">${esc(o.title)}</h1><div class="tags"><span class="tag">${esc(o.level)}</span><span class="tag">${esc(o.format)}</span><span class="tag">${esc(o.language)}</span>${o.city?`<span class="tag">${esc(o.city)}</span>`:''}</div><div class="panel"><h3>Об услуге</h3><p class="detail-copy">${esc(o.description)}</p></div><div class="panel"><h3>Ваш наставник</h3><a class="list-main" href="/#/user/${o.user_id}">${avatar(o.provider,true,o.provider_avatar)}<span><strong>${esc(o.provider)}</strong><small>${esc(o.provider_city||'Город не указан')} · ${o.rating?`★ ${o.rating}`:'Новый участник'}</small></span></a></div></div><aside class="side-sticky"><div class="panel"><span class="eyebrow">Обмен временем</span><div class="side-price">${o.min_minutes}–${o.max_minutes} мин</div><p class="muted">Один час помощи равен одному часу вашего времени.</p><div class="mini-info"><span>◷</span><div><strong>Удобная длительность</strong><small>От ${o.min_minutes} до ${o.max_minutes} минут</small></div></div><div class="mini-info"><span>◎</span><div><strong>${esc(o.format)}</strong><small>${o.format==='Офлайн'?esc(o.city):'Из любой точки'}</small></div></div><div style="display:flex;gap:8px;margin-top:18px"><button class="btn wide" data-action="book" data-id="${o.id}" ${state.user?.id===o.user_id?'disabled':''}>Отправить заявку ↗</button><button class="btn secondary icon" data-action="fav" data-id="${o.id}" aria-label="В избранное">${favorite?'♥':'♡'}</button></div>${state.user?.id===o.user_id?'<small class="muted">Это ваше предложение</small>':''}</div></aside></div></div></main>`);}
async function userPage(){loading();const d=await api('/users/'+routeId());const u=d.user;shell(`<main class="page"><div class="container"><div class="panel" style="margin-bottom:25px"><div class="list-main">${avatar(u.name,true,u.avatar_file)}<span><h1 style="font-size:32px;margin:0">${esc(u.name)}</h1><small>${esc(u.city||'Город не указан')} · Участник сообщества</small></span></div><p style="margin:18px 0 8px">${esc(u.bio||'Пока нет описания')}</p><div class="tags">${u.skills.split(',').filter(Boolean).map(x=>`<span class="tag">${esc(x.trim())}</span>`).join('')}</div></div><div class="section-head"><h2>Предложения</h2></div>${d.offers.length?`<div class="card-grid">${d.offers.map(o=>offerCard(o)).join('')}</div>`:empty('Пока нет предложений','Загляните позже.')}<div class="section-head" style="margin-top:40px"><h2>Отзывы</h2></div>${d.reviews.length?d.reviews.map(r=>`<div class="panel" style="margin-bottom:10px"><strong>★ ${r.rating} · ${esc(r.author)}</strong><p>${esc(r.body)}</p></div>`).join(''):empty('Пока нет отзывов','Отзывы появятся после завершённых обменов.')}</div></main>`);}
async function dashboard(){if(!state.user){authModal();nav('home');return;}loading();const [req,offers]=await Promise.all([api('/requests'),api('/my-offers')]);const recent=req.requests.slice(0,3);shell(`<main class="page"><div class="container"><div class="page-header"><div><span class="eyebrow">Личный кабинет</span><h1>Привет, ${esc(state.user.name.split(' ')[0])} 👋</h1><p>Ваше пространство для новых идей и полезных встреч.</p></div><button class="btn" data-action="new-offer">+ Новая услуга</button></div><div class="stats"><div class="stat accent"><small>Доступно минут</small><div class="number">${state.user.available}</div><a class="link" href="/#/wallet">Открыть кошелёк →</a></div><div class="stat"><small>В резерве</small><div class="number">${state.user.reserved}</div><small>Для подтверждённых встреч</small></div><div class="stat"><small>Мои предложения</small><div class="number">${offers.offers.length}</div><a class="link" href="/#/my-offers">Управлять →</a></div></div><div class="dashboard-grid"><div class="panel"><div class="section-head"><h3>Последние заявки</h3><a class="link" href="/#/requests">Все заявки →</a></div>${recent.length?recent.map(requestRow).join(''):empty('Пока нет заявок','Начните с поиска интересного навыка.','<a class="btn small" href="/#/catalog">Найти помощь</a>')}</div><div class="panel"><h3>Быстрый старт</h3><p class="muted">Расскажите о себе и добавьте навыки. Так другим будет проще доверить вам своё время.</p><button class="btn secondary wide" data-action="edit-profile">Редактировать профиль</button><div class="mini-info" style="margin-top:14px"><span>✳</span><div><strong>Начните с 120 минут</strong><small>Уже зачислены на ваш баланс</small></div></div></div></div></div></main>`);}
function requestRow(r){const other=state.user?.id===r.customer_id?r.provider:r.customer;return `<div class="list-row"><div class="list-main">${avatar(other)}<span><strong>${esc(r.title)}</strong><small>${esc(other)} · ${fmtDate(r.starts_at)} · ${r.minutes} мин</small></span></div><div class="list-actions">${status(r.status)}<a class="btn secondary small" href="/#/request/${r.id}">Открыть</a></div></div>`;}
async function requestsPage(){if(!requireLogin())return;loading();const d=await api('/requests');const tab=state.requestTab;const shown=d.requests.filter(r=>tab==='all'||(tab==='incoming'?r.provider_id===state.user.id:r.customer_id===state.user.id));shell(`<main class="page"><div class="container"><div class="page-header"><div><span class="eyebrow">Мои обмены</span><h1>Заявки и встречи</h1><p>Отслеживайте договорённости и завершайте обмены.</p></div><button class="btn" data-action="go-catalog">Найти помощь</button></div><div class="tabs">${[['all','Все заявки'],['incoming','Входящие'],['outgoing','Исходящие']].map(([id,label])=>`<button class="${tab===id?'active':''}" data-action="request-tab" data-tab="${id}">${label}</button>`).join('')}</div>${shown.length?shown.map(r=>`<div class="request-card"><div><span class="muted" style="font-size:11px">Заявка №${r.id} · ${r.customer_id===state.user.id?'Вы заказчик':'Вы исполнитель'}</span><h3>${esc(r.title)}</h3><p>${fmtDate(r.starts_at)} · ${r.minutes} мин · ${esc(r.format)}</p></div><div class="list-actions">${status(r.status)}<a class="btn secondary small" href="/#/request/${r.id}">Подробнее →</a></div></div>`).join(''):empty('Здесь пока пусто','Когда вы отправите или получите заявку, она появится здесь.')}</div></main>`);}
async function requestPage(){if(!requireLogin())return;loading();const d=await api('/requests/'+routeId()),r=d.request,customer=r.customer_id===state.user.id,provider=r.provider_id===state.user.id;const end=new Date(r.starts_at).getTime()+r.minutes*60000,started=Date.now()>=new Date(r.starts_at).getTime(),ended=Date.now()>=end,reviewed=d.reviews.some(x=>x.author_id===state.user.id);let actions='';if(r.status==='PENDING'){if(provider)actions=`<button class="btn" data-action="request-action" data-kind="accept" data-id="${r.id}">Принять заявку</button><button class="btn danger" data-action="request-action" data-kind="reject" data-id="${r.id}">Отклонить</button>`;if(customer)actions=`<button class="btn danger" data-action="request-action" data-kind="cancel" data-id="${r.id}">Отменить заявку</button>`;}if(r.status==='ACCEPTED'){if(!started)actions=`<button class="btn danger" data-action="request-action" data-kind="cancel" data-id="${r.id}">Отменить встречу</button>`;else actions=`${provider&&ended?`<button class="btn" data-action="request-action" data-kind="mark-done" data-id="${r.id}">Услуга оказана</button>`:''}<button class="btn outline" data-action="dispute" data-id="${r.id}">Открыть спор</button>`;}if(r.status==='AWAITING_CONFIRMATION')actions=`${customer?`<button class="btn" data-action="request-action" data-kind="confirm" data-id="${r.id}">Подтвердить выполнение</button>`:''}<button class="btn outline" data-action="dispute" data-id="${r.id}">Открыть спор</button>`;if(r.status==='COMPLETED'&&!reviewed)actions=`<button class="btn" data-action="review" data-id="${r.id}">Оставить отзыв</button>`;shell(`<main class="page"><div class="container"><p class="muted"><a href="/#/requests">Мои заявки</a> / №${r.id}</p><div class="page-header"><div><span class="eyebrow">Обмен знаниями</span><h1>${esc(r.title)}</h1><p>${customer?'Вы заказчик':'Вы исполнитель'} · ${esc(r.customer)} и ${esc(r.provider)}</p></div>${status(r.status)}</div><div class="detail-grid"><div><div class="panel"><h3>Информация о встрече</h3><div class="request-summary"><div class="summary-item"><small>Дата и время</small><strong>${fmtDate(r.starts_at)}</strong></div><div class="summary-item"><small>Длительность</small><strong>${r.minutes} минут</strong></div><div class="summary-item"><small>Формат</small><strong>${esc(r.format)}</strong></div></div>${r.note?`<p class="muted">Комментарий: ${esc(r.note)}</p>`:''}${d.dispute?`<div class="alert">Спор: ${esc(d.dispute.reason)}. ${esc(d.dispute.description)}</div>`:''}<div class="list-actions" style="flex-wrap:wrap">${actions}</div></div><div class="panel"><h3>Чат по заявке</h3>${r.status==='PENDING'?'<p class="muted">Чат откроется после принятия заявки.</p>':`<div class="chat">${d.messages.map(m=>`<div class="bubble ${m.user_id===state.user.id?'mine':m.user_id===null?'system':''}">${esc(m.body)}<small>${m.author?esc(m.author)+' · ':''}${fmtDate(m.created_at)}</small></div>`).join('')}</div>${['ACCEPTED','AWAITING_CONFIRMATION','DISPUTED','COMPLETED','RESOLVED'].includes(r.status)?`<form id="message-form" class="chat-form" data-id="${r.id}"><input class="input" name="message" maxlength="2000" placeholder="Напишите сообщение" required><button class="btn">Отправить</button></form>`:''}`}</div></div><aside><div class="panel"><h3>Как проходит обмен</h3><div class="mini-info"><span>1</span><div><strong>Заявка отправлена</strong><small>Ожидаем ответ исполнителя</small></div></div><div class="mini-info"><span>2</span><div><strong>Время в резерве</strong><small>После принятия заявки</small></div></div><div class="mini-info"><span>3</span><div><strong>Подтверждение</strong><small>После оказания услуги</small></div></div><div class="mini-info"><span>4</span><div><strong>Минуты переведены</strong><small>После подтверждения заказчиком</small></div></div></div></aside></div></div></main>`);}
async function walletPage(){if(!requireLogin())return;loading();const d=await api('/wallet');shell(`<main class="page"><div class="container"><div class="page-header"><div><span class="eyebrow">Мой кошелёк</span><h1>Ваше время</h1><p>Прозрачная история всех движений минут.</p></div></div><div class="wallet-hero"><div><small>Доступный баланс</small><strong>${d.available} минут</strong><p>Используйте их, чтобы учиться у других</p></div><span style="font-size:70px;color:#b9dfad">✳</span></div><div class="stats" style="grid-template-columns:repeat(2,1fr)"><div class="stat"><small>Зарезервировано</small><div class="number">${d.reserved}</div><small>Для принятых заявок</small></div><div class="stat"><small>Всего минут</small><div class="number">${d.available+d.reserved}</div><small>Доступно и в резерве</small></div></div><div class="panel"><h3>История операций</h3>${d.transactions.length?d.transactions.map(t=>`<div class="tx"><div><strong>${esc(({START_BONUS:'Стартовые минуты',RESERVE:'Резерв встречи',RELEASE:'Возврат резерва',SPEND:'Оплата встречи',EARN:'Получено за помощь',DISPUTE_REFUND:'Возврат по спору',DISPUTE_SPEND:'Списание по решению',DISPUTE_EARN:'Начисление по решению'})[t.type]||t.type)}</strong><small>${fmtDate(t.created_at)}${t.request_id?' · Заявка №'+t.request_id:''}</small></div><div class="${t.available_delta>=0?'plus':'minus'}">${t.available_delta>0?'+':''}${t.available_delta} мин${t.reserved_delta?` <small>Резерв: ${t.reserved_delta>0?'+':''}${t.reserved_delta}</small>`:''}</div></div>`).join(''):empty('Операций пока нет','Здесь появится история обменов.')}</div></div></main>`);}
async function myOffers(){if(!requireLogin())return;loading();const d=await api('/my-offers');shell(`<main class="page"><div class="container"><div class="page-header"><div><span class="eyebrow">Делитесь опытом</span><h1>Мои услуги</h1><p>Управляйте тем, чему готовы научить других.</p></div><button class="btn" data-action="new-offer">+ Новая услуга</button></div>${d.offers.length?d.offers.map(o=>`<div class="request-card"><div class="list-main"><span class="category-icon">${esc(o.category_icon)}</span><span><strong>${esc(o.title)}</strong><small>${esc(o.category)} · ${o.min_minutes}–${o.max_minutes} мин</small></span></div><div class="list-actions"><span class="status ${o.active?'ACCEPTED':''}">${o.active?'Активна':'Выключена'}</span><button class="btn secondary small" data-action="toggle-offer" data-id="${o.id}" data-active="${o.active}">${o.active?'Выключить':'Включить'}</button></div></div>`).join(''):empty('У вас пока нет услуг','Создайте предложение и поделитесь тем, что умеете.','<button class="btn small" data-action="new-offer">Предложить навык</button>')}</div></main>`);}
async function favorites(){if(!requireLogin())return;loading();const d=await api('/favorites');shell(`<main class="page"><div class="container"><div class="page-header"><div><span class="eyebrow">Сохранено для вас</span><h1>Избранное</h1><p>Все интересные предложения в одном месте.</p></div></div>${d.offers.length?`<div class="card-grid">${d.offers.map(o=>offerCard(o,d.offers.map(x=>x.id))).join('')}</div>`:empty('Здесь пока пусто','Сохраняйте понравившиеся услуги из каталога.','<a class="btn small" href="/#/catalog">В каталог</a>')}</div></main>`);}
async function profile(){if(!requireLogin())return;loading();shell(`<main class="page"><div class="container"><div class="page-header"><div><span class="eyebrow">Мой профиль</span><h1>${esc(state.user.name)}</h1><p>Расскажите о себе другим участникам.</p></div><div class="list-actions"><button class="btn secondary" data-action="edit-avatar">Выбрать аватарку</button><button class="btn" data-action="edit-profile">Редактировать</button></div></div><div class="panel"><div class="list-main">${avatar(state.user.name,true,state.user.avatar_file)}<span><strong>${esc(state.user.name)}</strong><small>${esc(state.user.city||'Город не указан')}</small></span></div><p style="margin-top:18px">${esc(state.user.bio||'Пока нет описания')}</p><div class="tags">${state.user.skills.split(',').filter(Boolean).map(s=>`<span class="tag">${esc(s.trim())}</span>`).join('')}</div><div class="mini-info"><span>◎</span><div><strong>Язык общения</strong><small>${esc(state.user.language)}</small></div></div><div class="mini-info"><span>✉</span><div><strong>Почта аккаунта</strong><small>${esc(state.user.email)}</small></div></div></div></div></main>`);}
async function notificationsPage(){if(!requireLogin())return;await refresh();shell(`<main class="page"><div class="container"><div class="page-header"><div><span class="eyebrow">На связи</span><h1>Уведомления</h1><p>Новости о ваших заявках, встречах и отзывах.</p></div>${state.notifications.some(n=>!n.read)?'<button class="btn secondary" data-action="read-notifications">Отметить прочитанными</button>':''}</div><div class="panel">${state.notifications.length?state.notifications.map(n=>`<div class="list-row"><div class="list-main"><span class="category-icon">${n.read?'○':'✳'}</span><span><strong>${esc(n.body)}</strong><small>${fmtDate(n.created_at)}</small></span></div>${n.read?'':'<span class="status ACCEPTED">Новое</span>'}</div>`).join(''):empty('Новых событий нет','Здесь появятся уведомления о ваших обменах.')}</div></div></main>`);}
async function admin(){if(!state.user||state.user.role!=='admin'){shell(`<main class="page"><div class="container">${empty('Доступ только для администратора','Войдите под администраторским аккаунтом.','<button class="btn" data-action="login">Войти</button>')}</div></main>`);return;}loading();const d=await api('/admin/dashboard'),tab=state.adminTab;let content='';if(tab==='overview')content=`<div class="admin-stats"><div class="stat accent"><small>Участники</small><div class="number">${d.stats.users}</div></div><div class="stat"><small>Активные услуги</small><div class="number">${d.stats.offers}</div></div><div class="stat"><small>Все заявки</small><div class="number">${d.stats.requests}</div></div><div class="stat"><small>Открытые споры</small><div class="number">${d.stats.disputes}</div></div></div><div class="panel"><h3>Требуют внимания</h3>${d.disputes.filter(x=>x.status==='OPEN').length?d.disputes.filter(x=>x.status==='OPEN').map(x=>`<div class="list-row"><div><strong>Спор №${x.id}: ${esc(x.title)}</strong><small style="display:block;color:var(--muted)">${esc(x.customer)} / ${esc(x.provider)} · ${x.minutes} мин</small></div><button class="btn small" data-action="admin-tab" data-tab="disputes">Рассмотреть</button></div>`).join(''):empty('Всё спокойно','Сейчас нет споров, требующих решения.')}</div>`;if(tab==='disputes')content=`<div class="panel"><h3>Споры</h3>${d.disputes.length?d.disputes.map(x=>`<div class="request-card"><div><span class="status ${x.status==='OPEN'?'DISPUTED':'RESOLVED'}">${x.status==='OPEN'?'Открыт':'Решён'}</span><h3>№${x.id} · ${esc(x.title)}</h3><p>${esc(x.customer)} / ${esc(x.provider)} · ${x.minutes} минут</p><p><strong>${esc(x.reason)}</strong> — ${esc(x.description)}</p></div><div class="list-actions"><a class="btn secondary small" href="/#/request/${x.request_id}">Заявка</a>${x.status==='OPEN'?`<button class="btn small" data-action="resolve" data-id="${x.id}">Решить</button>`:''}</div></div>`).join(''):empty('Споров нет','Новые споры появятся здесь.')}</div>`;if(tab==='users')content=adminUsers(d);if(tab==='offers')content=`<div class="panel table-wrap"><table class="admin-table"><thead><tr><th>Предложение</th><th>Исполнитель</th><th>Категория</th><th>Статус</th><th></th></tr></thead><tbody>${d.offers.map(o=>`<tr><td>${esc(o.title)}</td><td>${esc(o.provider)}</td><td>${esc(o.category)}</td><td>${o.hidden?'<span class="status DISPUTED">Скрыто</span>':'<span class="status ACCEPTED">Видно</span>'}</td><td><button class="btn ${o.hidden?'secondary':'danger'} small" data-action="admin-toggle" data-kind="offers" data-id="${o.id}">${o.hidden?'Показать':'Скрыть'}</button></td></tr>`).join('')}</tbody></table></div>`;if(tab==='reviews')content=`<div class="panel"><h3>Отзывы</h3>${d.reviews.length?d.reviews.map(x=>`<div class="request-card"><div><strong>★ ${x.rating} · ${esc(x.author)} → ${esc(x.recipient)}</strong><p>${esc(x.body)}</p></div><button class="btn ${x.hidden?'secondary':'danger'} small" data-action="admin-toggle" data-kind="reviews" data-id="${x.id}">${x.hidden?'Показать':'Скрыть'}</button></div>`).join(''):empty('Отзывов пока нет','После завершённых обменов они появятся здесь.')}</div>`;if(tab==='categories')content=`<div class="panel"><h3>Категории</h3><div class="tags">${d.categories.map(c=>`<span class="tag">${esc(c.icon)} ${esc(c.name)}</span>`).join('')}</div><form id="category-form" class="chat-form"><input class="input" name="icon" placeholder="✦" maxlength="4" style="width:72px"><input class="input" name="name" placeholder="Название категории" required maxlength="60"><button class="btn">Добавить</button></form></div>`;if(tab==='audit')content=`<div class="panel"><h3>История действий</h3>${d.audit.length?d.audit.map(x=>`<div class="tx"><div><strong>${esc(x.action)} · ${esc(x.target)}</strong><small>${esc(x.admin)} · ${fmtDate(x.created_at)}</small></div><div class="admin-reason">${esc(x.note)}</div></div>`).join(''):empty('Пока пусто','Административные действия появятся здесь.')}</div>`;app.innerHTML=header()+`<div class="admin-shell"><aside class="admin-sidebar"><span class="eyebrow">Панель управления</span><nav class="admin-nav">${[['overview','◈ Обзор'],['disputes','⚑ Споры'],['users','♙ Участники'],['offers','✳ Услуги'],['reviews','★ Отзывы'],['categories','▦ Категории'],['audit','◷ Журнал']].map(([id,label])=>`<button class="${tab===id?'active':''}" data-action="admin-tab" data-tab="${id}">${label}</button>`).join('')}</nav></aside><main class="admin-main"><div class="page-header"><div><span class="eyebrow">Администрирование</span><h1>${({overview:'Обзор платформы',disputes:'Разбор споров',users:'Участники',offers:'Предложения',reviews:'Отзывы',categories:'Категории',audit:'Журнал действий'})[tab]}</h1><p>Следите за безопасностью сообщества и решайте вопросы участников.</p></div></div>${content}</main></div>`;}
function modal(title,content){modalRoot.innerHTML=`<div class="modal-backdrop" data-action="close-backdrop"><div class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-top"><h2>${esc(title)}</h2><button class="close" data-action="close-modal" aria-label="Закрыть">×</button></div>${content}</div></div>`;setTimeout(()=>modalRoot.querySelector('input,select,button:not(.close)')?.focus(),20);}
function closeModal(){modalRoot.innerHTML='';}
function authModal(mode='login'){const register=mode==='register';modal(register?'Создать аккаунт':'Рады вас видеть',`<p class="muted">${register?'Присоединяйтесь к сообществу и получите 120 стартовых минут.':'Войдите, чтобы продолжить обмен знаниями.'}</p><form id="auth-form" data-mode="${mode}">${register?`<div class="field"><label class="label">Ваше имя</label><input class="input" name="name" required minlength="2" autocomplete="name" placeholder="Как вас зовут?"></div>`:''}<div class="field"><label class="label">Электронная почта</label><input class="input" type="email" name="email" required autocomplete="email" placeholder="you@example.com"></div><div class="field"><label class="label">Пароль</label><input class="input" type="password" name="password" required minlength="8" autocomplete="${register?'new-password':'current-password'}" placeholder="Минимум 8 символов"></div><button class="btn wide">${register?'Зарегистрироваться':'Войти'}</button></form><div class="auth-switch">${register?'Уже есть аккаунт?':'Впервые у нас?'} <button data-action="${register?'login':'register'}">${register?'Войти':'Создать аккаунт'}</button></div>`);}
function offerModal(){if(!requireLogin())return;modal('Новое предложение',`<p class="muted">Поделитесь навыком, который поможет другому человеку.</p><form id="offer-form"><div class="field"><label class="label">Название</label><input class="input" name="title" required minlength="5" maxlength="100" placeholder="Например, основы Figma"></div><div class="field"><label class="label">Описание</label><textarea class="textarea" name="description" required minlength="20" maxlength="1000" placeholder="Расскажите, чему научите и как пройдёт встреча"></textarea></div><div class="form-grid"><div class="field"><label class="label">Категория</label><select class="select" name="category_id" required><option value="">Выберите</option>${state.categories.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label class="label">Уровень</label><select class="select" name="level"><option>Начинающий</option><option>Средний</option><option>Продвинутый</option><option>Любой</option></select></div><div class="field"><label class="label">Формат</label><select class="select" name="format"><option>Онлайн</option><option>Офлайн</option></select></div><div class="field"><label class="label">Город для офлайн встреч</label><input class="input" name="city" maxlength="80" placeholder="Алматы"></div><div class="field"><label class="label">От, минут</label><select class="select" name="min_minutes">${[30,60,90,120,150,180,210,240].map(n=>`<option ${n===30?'selected':''}>${n}</option>`).join('')}</select></div><div class="field"><label class="label">До, минут</label><select class="select" name="max_minutes">${[30,60,90,120,150,180,210,240].map(n=>`<option ${n===120?'selected':''}>${n}</option>`).join('')}</select></div><div class="field full"><label class="label">Язык общения</label><input class="input" name="language" value="Русский" required maxlength="60"></div></div><button class="btn wide">Опубликовать предложение</button></form>`);}
async function bookingModal(id){if(!requireLogin())return;const {offer:o}=await api('/offers/'+id);const min=new Date(Date.now()+20*60000);min.setMinutes(Math.ceil(min.getMinutes()/30)*30,0,0);const local=new Date(min.getTime()-min.getTimezoneOffset()*60000).toISOString().slice(0,16);modal('Отправить заявку',`<div class="modal-note"><strong>${esc(o.title)}</strong><br>Минуты спишутся в резерв после принятия заявки исполнителем.</div><form id="booking-form" data-id="${o.id}"><div class="form-grid"><div class="field"><label class="label">Длительность</label><select class="select" name="minutes">${[30,60,90,120,150,180,210,240].filter(n=>n>=o.min_minutes&&n<=o.max_minutes).map(n=>`<option>${n}</option>`).join('')}</select></div><div class="field"><label class="label">Формат</label><input class="input" name="format" value="${esc(o.format)}" readonly></div></div><div class="field"><label class="label">Дата и время встречи</label><input class="input" type="datetime-local" name="starts_at" min="${local}" required></div><div class="field"><label class="label">Комментарий исполнителю</label><textarea class="textarea" name="note" maxlength="500" placeholder="Расскажите, чему хотите научиться"></textarea></div><button class="btn wide">Отправить заявку</button></form>`);}
function profileModal(){const u=state.user;modal('Редактировать профиль',`<form id="profile-form"><div class="field"><label class="label">Имя</label><input class="input" name="name" value="${esc(u.name)}" required minlength="2"></div><div class="field"><label class="label">Город</label><input class="input" name="city" value="${esc(u.city)}"></div><div class="field"><label class="label">О себе</label><textarea class="textarea" name="bio">${esc(u.bio)}</textarea></div><div class="field"><label class="label">Навыки через запятую</label><input class="input" name="skills" value="${esc(u.skills)}"></div><div class="field"><label class="label">Язык общения</label><input class="input" name="language" value="${esc(u.language)}"></div><button class="btn wide">Сохранить изменения</button></form>`);}
function disputeModal(id){modal('Открыть спор',`<p class="muted">Опишите ситуацию. Минуты останутся в резерве до решения администратора.</p><form id="dispute-form" data-id="${id}"><div class="field"><label class="label">Причина</label><input class="input" name="reason" required minlength="3" maxlength="100" placeholder="Что произошло?"></div><div class="field"><label class="label">Подробности</label><textarea class="textarea" name="description" required minlength="10" maxlength="1000"></textarea></div><button class="btn wide">Передать на рассмотрение</button></form>`);}
function reviewModal(id){modal('Оставить отзыв',`<form id="review-form" data-id="${id}"><div class="field"><label class="label">Оценка</label><select class="select" name="rating">${[5,4,3,2,1].map(n=>`<option value="${n}">${'★'.repeat(n)} (${n})</option>`).join('')}</select></div><div class="field"><label class="label">Ваш отзыв</label><textarea class="textarea" name="body" required minlength="5" maxlength="800" placeholder="Как прошла встреча?"></textarea></div><button class="btn wide">Опубликовать отзыв</button></form>`);}
function resolveModal(id){modal('Решение по спору',`<p class="muted">Решение сразу переведёт или вернёт зарезервированные минуты.</p><form id="resolve-form" data-id="${id}"><div class="field"><label class="label">Решение</label><select class="select" name="resolution"><option value="refund">Вернуть минуты заказчику</option><option value="transfer">Перевести минуты исполнителю</option></select></div><div class="field"><label class="label">Основание решения</label><textarea class="textarea" name="note" required minlength="5" maxlength="500"></textarea></div><button class="btn wide">Подтвердить решение</button></form>`);}
function reasonModal(kind,id){modal('Причина действия',`<form id="reason-form" data-kind="${kind}" data-id="${id}"><div class="field"><label class="label">Причина для журнала</label><textarea class="textarea" name="note" required minlength="3" maxlength="300"></textarea></div><button class="btn wide">Применить</button></form>`);}
async function refresh(){const d=await api('/bootstrap');state.user=d.user;state.categories=d.categories;state.notifications=d.notifications;}
async function render(){try{const r=route();if(r==='home')await home();else if(r==='catalog')await catalog();else if(r==='offer')await offerPage();else if(r==='user')await userPage();else if(r==='dashboard')await dashboard();else if(r==='requests')await requestsPage();else if(r==='request')await requestPage();else if(r==='wallet')await walletPage();else if(r==='my-offers')await myOffers();else if(r==='favorites')await favorites();else if(r==='profile')await profile();else if(r==='notifications')await notificationsPage();else if(r==='admin')await admin();else nav('home');}catch(e){shell(`<main class="page"><div class="container">${empty('Не удалось загрузить страницу',e.message,'<button class="btn" data-action="retry">Повторить</button>')}</div></main>`);}}
document.addEventListener('click',async e=>{const action=e.target.closest('[data-action]')?.dataset.action;if(action==='notifications')nav('notifications');if(action==='read-notifications'){try{await post('/notifications/read');await refresh();render();}catch(err){error(err);}}});
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;try{if(a==='close-backdrop'&&e.target===el)closeModal();else if(a==='close-modal')closeModal();else if(a==='menu')document.querySelector('#nav')?.classList.toggle('open');else if(a==='login'||a==='register')authModal(a);else if(a==='new-offer')offerModal();else if(a==='go-catalog')nav('catalog');else if(a==='category'){state.filters.category=el.dataset.id;state.filters.page=1;nav('catalog');render();}else if(a==='page'){state.filters.page=Number(el.dataset.page);render();window.scrollTo(0,0);}else if(a==='book')bookingModal(el.dataset.id);else if(a==='edit-profile')profileModal();else if(a==='profile-menu')modal('Мой аккаунт',`<div class="list-main" style="margin-bottom:20px">${avatar(state.user.name,true,state.user.avatar_file)}<span><strong>${esc(state.user.name)}</strong><small>${esc(state.user.email)}</small></span></div><div style="display:grid;gap:8px"><button class="btn secondary wide" data-action="profile-link">Мой кабинет</button><button class="btn secondary wide" data-action="favorites-link">Избранное</button><button class="btn secondary wide" data-action="profile-page">Мой профиль</button>${state.user.role==='admin'?'<button class="btn secondary wide" data-action="admin-link">Админ-панель</button>':''}<button class="btn outline wide" data-action="logout">Выйти</button></div>`);else if(['profile-link','favorites-link','profile-page','admin-link'].includes(a)){closeModal();nav(({ 'profile-link':'dashboard','favorites-link':'favorites','profile-page':'profile','admin-link':'admin' })[a]);}else if(a==='logout'){await post('/auth/logout');closeModal();await refresh();nav('home');render();}else if(a==='fav'){if(!requireLogin())return;const result=await post('/favorites/'+el.dataset.id);toast(result.favorite?'Добавлено в избранное':'Удалено из избранного');render();}else if(a==='toggle-offer'){await patch('/offers/'+el.dataset.id,{active:el.dataset.active!=='1'});toast('Предложение обновлено');render();}else if(a==='request-tab'){state.requestTab=el.dataset.tab;render();}else if(a==='request-action'){if(!confirm(({accept:'Принять заявку и зарезервировать минуты?',reject:'Отклонить заявку?',cancel:'Отменить заявку?', 'mark-done':'Отметить услугу оказанной?',confirm:'Подтвердить выполнение и перевести минуты?'})[el.dataset.kind]))return;await post(`/requests/${el.dataset.id}/${el.dataset.kind}`);await refresh();toast('Заявка обновлена');render();}else if(a==='dispute')disputeModal(el.dataset.id);else if(a==='review')reviewModal(el.dataset.id);else if(a==='admin-tab'){state.adminTab=el.dataset.tab;render();}else if(a==='resolve')resolveModal(el.dataset.id);else if(a==='admin-toggle')reasonModal(el.dataset.kind,el.dataset.id);else if(a==='retry')render();}catch(err){error(err);}});
document.addEventListener('submit',async e=>{const f=e.target;if(!f.id)return;e.preventDefault();const b=Object.fromEntries(new FormData(f));const button=f.querySelector('[type=submit],button:not([type])');if(button)button.disabled=true;try{if(f.id==='filters'){state.filters={...state.filters,...b,page:1};return render();}if(f.id==='auth-form'){const d=await post('/auth/'+f.dataset.mode,b);state.user=d.user;await refresh();closeModal();toast(f.dataset.mode==='register'?'Аккаунт создан. Вам начислено 120 минут!':'С возвращением!');if(state.user.role==='admin')nav('admin');else nav('dashboard');render();}else if(f.id==='offer-form'){await post('/offers',b);closeModal();toast('Предложение опубликовано');nav('my-offers');render();}else if(f.id==='booking-form'){b.offer_id=Number(f.dataset.id);b.minutes=Number(b.minutes);b.starts_at=new Date(b.starts_at).toISOString();const d=await post('/requests',b);closeModal();toast('Заявка отправлена');nav('request/'+d.id);render();}else if(f.id==='profile-form'){const d=await patch('/profile',b);state.user=d.user;closeModal();toast('Профиль обновлён');render();}else if(f.id==='message-form'){await post(`/requests/${f.dataset.id}/messages`,b);render();}else if(f.id==='dispute-form'){await post(`/requests/${f.dataset.id}/dispute`,b);closeModal();toast('Спор открыт');render();}else if(f.id==='review-form'){b.rating=Number(b.rating);await post(`/requests/${f.dataset.id}/reviews`,b);closeModal();toast('Спасибо за отзыв!');render();}else if(f.id==='resolve-form'){await post(`/admin/disputes/${f.dataset.id}/resolve`,b);closeModal();toast('Спор рассмотрен');render();}else if(f.id==='reason-form'){await post(`/admin/${f.dataset.kind}/${f.dataset.id}/toggle`,b);closeModal();toast('Изменение сохранено');render();}else if(f.id==='category-form'){await post('/admin/categories',b);await refresh();toast('Категория добавлена');render();}}catch(err){error(err);}finally{if(button)button.disabled=false;}});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();});
refresh().then(render).catch(error);

function adminUsers(d){
  return `<div class="panel"><div class="section-head"><div><h3>Участники и администраторы</h3><p class="muted">Назначение роли завершит текущие сеансы участника.</p></div><button class="btn small" data-action="admin-create-user">+ Добавить аккаунт</button></div><div class="table-wrap"><table class="admin-table"><thead><tr><th>Имя и почта</th><th>Город</th><th>Роль</th><th>Минуты</th><th>Статус</th><th>Действия</th></tr></thead><tbody>${d.users.map(u=>`<tr><td>${esc(u.name)}<small style="display:block;color:var(--muted)">${esc(u.email)}</small></td><td>${esc(u.city||'—')}</td><td><span class="status ${u.role==='admin'?'RESOLVED':'ACCEPTED'}">${u.role==='admin'?'Администратор':'Пользователь'}</span></td><td>${u.available} / ${u.reserved} в резерве</td><td>${u.blocked?'<span class="status DISPUTED">Заблокирован</span>':'<span class="status ACCEPTED">Активен</span>'}</td><td><div class="list-actions">${u.id!==state.user.id?`<button class="btn secondary small" data-action="admin-role" data-id="${u.id}" data-role="${esc(u.role)}" data-name="${esc(u.name)}">${u.role==='admin'?'Снять роль':'Назначить админом'}</button>`:''}${u.role==='user'?`<button class="btn ${u.blocked?'secondary':'danger'} small" data-action="admin-toggle" data-kind="users" data-id="${u.id}">${u.blocked?'Разблокировать':'Блокировать'}</button>`:''}</div></td></tr>`).join('')}</tbody></table></div></div>`;
}
function createUserModal(){modal('Новый аккаунт',`<p class="muted">Создайте обычного участника или администратора. Для входа передайте ему почту и временный пароль безопасным способом.</p><form id="admin-create-user-form"><div class="field"><label class="label">Имя</label><input class="input" name="name" minlength="2" maxlength="80" required></div><div class="field"><label class="label">Почта</label><input class="input" type="email" name="email" required></div><div class="field"><label class="label">Временный пароль</label><input class="input" type="password" name="password" minlength="8" autocomplete="new-password" required></div><div class="field"><label class="label">Роль</label><select class="select" name="role"><option value="user">Обычный пользователь</option><option value="admin">Администратор</option></select></div><button class="btn wide">Создать аккаунт</button></form>`);}
function roleModal(id,currentRole,name){const next=currentRole==='admin'?'user':'admin';modal('Изменить роль',`<p class="muted">${esc(name)}: ${next==='admin'?'назначить администратором':'снять права администратора'}. Пользователю потребуется войти заново.</p><form id="admin-role-form" data-id="${id}"><input type="hidden" name="role" value="${next}"><div class="field"><label class="label">Причина изменения</label><textarea class="textarea" name="note" minlength="3" maxlength="300" required></textarea></div><button class="btn wide">Подтвердить</button></form>`);}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;if(el.dataset.action==='admin-create-user'){e.stopImmediatePropagation();createUserModal();}if(el.dataset.action==='admin-role'){e.stopImmediatePropagation();roleModal(Number(el.dataset.id),el.dataset.role,el.dataset.name);}},true);
document.addEventListener('submit',async e=>{const f=e.target;if(!['admin-create-user-form','admin-role-form'].includes(f.id))return;e.preventDefault();e.stopImmediatePropagation();const btn=f.querySelector('button');btn.disabled=true;try{const values=Object.fromEntries(new FormData(f));if(f.id==='admin-create-user-form'){await post('/admin/users',values);toast('Аккаунт создан');}else{await patch(`/admin/users/${f.dataset.id}/role`,values);toast('Роль обновлена');}closeModal();render();}catch(err){error(err);}finally{btn.disabled=false;}},true);

function avatarModal(){
  const current=state.user.avatar_file?`<img src="${esc(state.user.avatar_file)}" alt="Текущая аватарка">`:avatar(state.user.name,true);
  modal('Выбрать аватарку',`<form id="avatar-form"><div id="avatar-preview" class="avatar-upload-preview">${current}</div><div class="field"><label class="label" for="avatar-file">Фото с устройства</label><input id="avatar-file" class="input" type="file" name="avatar" accept="image/png,image/jpeg,image/webp" required></div><p class="muted">Изображение будет обрезано до квадрата и сохранено в профиле.</p><button class="btn wide">Сохранить аватарку</button></form>`);
}
document.addEventListener('click',e=>{if(e.target.closest('[data-action="edit-avatar"]')){e.preventDefault();e.stopImmediatePropagation();avatarModal();}},true);
document.addEventListener('change',e=>{if(e.target.id!=='avatar-file')return;const file=e.target.files?.[0];if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)){error(Error('Выберите PNG, JPEG или WebP'));return;}const reader=new FileReader();reader.onload=()=>{const preview=document.querySelector('#avatar-preview');if(preview)preview.innerHTML=`<img src="${reader.result}" alt="Предпросмотр аватарки">`;};reader.readAsDataURL(file);});
document.addEventListener('submit',async e=>{
  const form=e.target;if(form.id!=='avatar-form')return;e.preventDefault();e.stopImmediatePropagation();const button=form.querySelector('button');button.disabled=true;
  try{const file=form.querySelector('#avatar-file').files?.[0];if(!file||!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>10_000_000)throw Error('Выберите PNG, JPEG или WebP размером до 10 МБ');const bitmap=await createImageBitmap(file);const canvas=document.createElement('canvas');canvas.width=256;canvas.height=256;const ctx=canvas.getContext('2d');const side=Math.min(bitmap.width,bitmap.height),x=(bitmap.width-side)/2,y=(bitmap.height-side)/2;ctx.drawImage(bitmap,x,y,side,side,0,0,256,256);bitmap.close();const result=await post('/profile/avatar',{image:canvas.toDataURL('image/png')});state.user=result.user;closeModal();toast('Аватарка сохранена');render();}
  catch(err){error(err);}finally{button.disabled=false;}
},true);
